const seen = $getWorkflowStaticData('global');
if (!seen.sentLinks) seen.sentLinks = [];

const cutoffMs = Date.now() - 24 * 60 * 60 * 1000;
const normalized = [];

for (const item of $input.all()) {
  const j = item.json;
  let title, link, publishedMs;

  if (j.story) {
    title = j.story.title;
    link = j.story.url || ('https://news.ycombinator.com/item?id=' + j.story.objectID);
    publishedMs = j.story.created_at ? new Date(j.story.created_at).getTime() : Date.now();
  } else {
    title = j.title;
    link = j.link;
    publishedMs = j.isoDate ? new Date(j.isoDate).getTime() : (j.pubDate ? new Date(j.pubDate).getTime() : Date.now());
  }

  if (!title || !link) continue;
  if (seen.sentLinks.includes(link)) continue;
  if (publishedMs < cutoffMs) continue;

  normalized.push({ title, link, publishedMs });
  seen.sentLinks.push(link);
}

if (seen.sentLinks.length > 500) {
  seen.sentLinks = seen.sentLinks.slice(-500);
}

normalized.sort((a, b) => b.publishedMs - a.publishedMs);
const top = normalized.slice(0, 15);

const articlesText = top.map((a, i) => (i + 1) + '. ' + a.title + ' - ' + a.link).join('\n');

return [{ json: { articlesText: articlesText, count: top.length } }];

