=You are an expert AI Career Analyst writing a daily GenAI/Agentic AI briefing. 
Analyze the following headlines and extract a structured JSON object.
You MUST output ONLY a valid JSON object. Do not include markdown formatting, backticks, or text outside the JSON.

The JSON must match this exact schema:
{
  "sentiment": {
    "score": "Bullish, Bearish, or Neutral",
    "reason": "1 sentence explanation of the market mood"
  },
  "top_news": [
    {"headline": "title", "impact": "1-2 lines on why it matters"}
  ],
  "models_tools": [
    "model/tool name 1", "model/tool name 2"
  ],
  "skills": [
    {"skill": "Skill Name", "reason": "Why it's relevant this week"}
  ],
  "industry_impact": "2-3 sentences on how this affects engineering roles"
}

Headlines:
{{ $json.articlesText }}

parameters.jsCode:
try {
  let parsed = $input.first().json.text;
  if (typeof parsed === 'string') {
    // Strip markdown JSON wrappers if the LLM leaked them
    parsed = parsed.replace(/^```json/, '').replace(/```$/, '').trim();
    parsed = JSON.parse(parsed);
  }

  let html = `<div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; color: #333;">`;

  // Header & Sentiment
  html += `<h2 style="color: #2c3e50; border-bottom: 2px solid #3498db; padding-bottom: 5px;">Market Sentiment: ${parsed.sentiment.score}</h2>`;
  html += `<p style="font-style: italic; color: #555;">${parsed.sentiment.reason}</p>`;

  // Top News
  html += `<h3 style="color: #2980b9;">🔥 Top News Today</h3><ul>`;
  for (const item of parsed.top_news) {
    html += `<li style="margin-bottom: 10px;"><strong>${item.headline}</strong><br><span style="font-size: 0.9em; color: #666;">${item.impact}</span></li>`;
  }
  html += `</ul>`;

  // Models & Tools
  html += `<h3 style="color: #8e44ad;">🤖 New Models & Tools</h3><ul>`;
  if (parsed.models_tools && parsed.models_tools.length > 0) {
    for (const tool of parsed.models_tools) {
      html += `<li>${tool}</li>`;
    }
  } else {
    html += `<li>No major releases in today's headlines.</li>`;
  }
  html += `</ul>`;

  // Skills
  html += `<h3 style="color: #27ae60;">🛠️ Skills to Improve</h3><ul>`;
  for (const skill of parsed.skills) {
    html += `<li><strong>${skill.skill}:</strong> ${skill.reason}</li>`;
  }
  html += `</ul>`;

  // Impact
  html += `<h3 style="color: #d35400;">💼 Industry Impact</h3>`;
  html += `<p>${parsed.industry_impact}</p>`;

  html += `</div>`;

  return [{ json: { htmlEmail: html } }];
} catch (e) {
  return [{ json: { htmlEmail: "<p>Error parsing AI Output. Raw text:</p><pre>" + $input.first().json.text + "</pre>" } }];
}
